"def parse_ttl(ttl_str):
    """Convert a human TTL string (e.g. 24h, 3d, 7d, never) to seconds."""
    if not ttl_str or ttl_str.lower() in ["never", "permanent", "inf", "0"]:
        return None
    ttl_str = ttl_str.strip().lower()
    m = re.match(r"^(\d+)([smhdwy]?)$", ttl_str)
    if not m:
        return 24 * 3600  # Default to 24 hours
    val, unit = int(m.group(1)), m.group(2)
    multipliers = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400, 'w': 604800, 'y': 31536000}
    return val * multipliers.get(unit, 3600)


